window.DOSIK=window.DOSIK||{};DOSIK["bm_4"]={"1":[{"t":"table","title":"등기기록과 등기능력","head":["항목","내용"],"rows":[["등기기록·등기부","1필의 토지 또는 1개의 건물에 관한 등기정보자료가 등기기록 · 등기정보자료를 대법원규칙에 따라 편성한 것이 등기부(부동산등기법 제2조)"],["등기기록 구성","등기기록에는 표제부·갑구(소유권)·을구(소유권 외의 권리)를 둔다 · 구분건물은 1동 전체에 1개의 등기기록을 쓴다 · 1동의 표제부에는 대지권의 목적인 토지의 표시란, 전유부분의 표제부에는 대지권종류·대지권비율란을 둔다"],["등기능력 있는 물건","건물은 토지에 견고하게 정착하고 지붕과 벽(주벽)을 갖추어야 등기할 수 있다 · 콘테이너 구조·지붕으로 등재된 건축물은 보존등기를 못 한다"],["보존등기 가능","철근콘크리트 기초에 정착하고 내구성 있는 필름으로 벽과 지붕을 갖춘 고정식 비닐온실 · 견고하게 부착된 유류저장탱크 · 모두 보존등기 가능"],["개방형 축사","개방형 축사는 연면적 100제곱미터 초과 등 특례법 요건을 갖추면 등기 가능 · 증축 뒤 요건을 갖춘 때에는 그때 대장상 소유자가 보존등기 신청"],["등기할 수 없는 대상","공유수면, 공해상의 수중암초, 군사분계선 이북 토지, 구조상 공용부분은 등기능력 없다 · 구분소유의 물리적 요건을 못 갖춘 건물 부분은 구분건물로 등기되어도 · 경매로 매각되어도 그 등기가 무효라 매수인이 소유권을 얻지 못한다"],["하천 등기","하천법상 하천은 소유권보존·이전, 저당권설정, 신탁등기는 가능 · 지상권·지역권·전세권·임차권 등기는 불가"]]},{"t":"table","title":"구분점포·관할·부기등기","head":["항목","내용"],"rows":[["구분점포","구분점포는 판매·운수시설이고 경계표지와 건물번호표지가 견고하면 가능 · 바닥면적 1천제곱미터 요건은 2020년 집합건물법 개정으로 없어졌다"],["관할 지정","부동산이 여러 등기소 관할에 걸치면 상급법원의 장이 관할 등기소 지정 · 지정신청은 어느 관할 등기소에 내도 됨 · 이미 등기된 건물이 부속건물 신축으로 여러 관할에 걸치게 된 때에는 지정신청 없이 종전 등기소에 신청"],["관련 사건 특례","관할 등기소가 다른 여러 부동산이라도 등기목적과 등기원인이 같은 경우 · 그중 한 등기소에 관련 사건으로 신청 가능(제7조의2), 상속·유증 등기는 관할 아닌 등기소도 처리 가능(제7조의3) · 관할 위반 등기는 제29조 제1호로 각하, 마친 뒤 발견하면 직권말소한다"],["부기등기 순위","부기등기의 순위는 주등기의 순위에 따르고 · 같은 주등기에 붙은 부기등기끼리는 등기한 순서에 따른다(제5조)"],["부기로 하는 등기","환매특약·권리소멸약정·권리질권·가등기상 권리의 이전등기는 부기로 함 · 변경등기는 이해관계인의 승낙이 없으면 주등기로 함"],["말소 시 부기","주등기를 말소하면 부기등기는 직권으로 함께 말소되므로 집행법원은 주등기만 말소촉탁 · 이전 원인이 무효인 근저당권 이전의 부기등기는 부기등기만 말소"]]},{"t":"table","title":"중복등기","head":["항목","내용"],"rows":[["토지 중복 정리","최종 소유권 명의인이 같으면 후등기기록 폐쇄 · 후등기기록에만 소유권 외의 권리 등에 관한 등기가 있으면 선등기기록 폐쇄(부동산등기규칙 제34조)"],["명의 이전 중복","한쪽 명의인이 다른 쪽 명의인으로부터 소유권을 이전받은 경우 · 그 다른 등기기록이 후등기기록이거나 다른 권리 등기가 없는 선등기기록이면 폐쇄(제35조) · 원시취득이나 분배농지 상환완료를 원인으로 한 등기가 한쪽에만 있으면 나머지를 폐쇄한다"],["정리 절차","명의인이 같을 때에는 사전 통지 불필요 · 폐쇄는 실체관계에 영향 없음"],["건물 중복등기","건물 중복등기에서 보존등기명의인이 같으면 선행 등기기록을 기초로 한 신청만 수리 · 명의인이 다르면 어느 쪽 등기기록을 기초로 한 신청도 수리"],["중복 판단","토지 대장상 분할된 일부에 다시 보존등기가 된 경우 그 부분은 중복등기 · 존재하지 않는 토지에 대한 등기나 기재 착오로 지번만 같아진 등기기록은 중복등기로 처리하지 않음"]]},{"t":"table","title":"등기관의 심사와 열람","head":["항목","내용"],"rows":[["형식적 심사","등기관은 실질적 심사권 없이 신청정보·첨부정보와 등기기록만으로 형식적 심사 · 심사 기준시는 등기를 실행하려는 때이다 · 촉탁서와 첨부 판결의 일치 여부는 심사한다"],["판결 본등기·경정","판결이유로 가등기에 의한 본등기임이 명백하면 그 판결로 본등기 신청 가능 · 등기관의 잘못으로 생긴 착오는 지체 없이 직권경정, 이해관계 있는 제3자가 있으면 승낙 필요 · 멸실등기 전 멸실 건물에 된 가압류등기는 직권말소 불가"],["열람 범위","등기기록은 누구나 열람 가능 · 신청정보·첨부정보는 이해관계 있는 부분만 열람 · 등기 완료 전에는 열람 불가, 수사기관도 영장이 있어야 함"],["열람·수수료","앞 순위 근저당권의 신청정보는 후순위 근저당권자가 열람 가능, 반대는 불가 · 수수료 면제는 법률 규정이 있을 때만 · 인터넷 열람·발급 수수료는 면제하지 않음"],["장부 보존기간","신청서 접수장과 부속서류 편철장 5년 · 이의신청서류 편철장 10년이다(부동산등기규칙 제25조)"]]}],"2":[{"t":"table","title":"접수·보정·취하","head":["항목","내용"],"rows":[["접수 시기","등기신청은 부동산을 구별하는 정보가 전산정보처리조직에 저장된 때 접수된 것으로 봄 · 같은 부동산에 동시에 낸 신청에는 같은 접수번호 부여 · 접수증은 신청인의 청구가 있을 때 발급"],["일괄신청","일괄신청은 등기목적과 등기원인이 같아야 함 · 소유자가 다른 두 토지를 한 사람에게 각각 판 경우는 불가 · 같은 채권을 담보하는 공동저당은 소유자가 달라도 가능"],["신탁등기 일괄","신탁등기는 소유권이전등기와 1건의 신청정보로 일괄 신청"],["보정","보정 통지는 조사를 마친 즉시 구두·전화·모사전송으로 함 · 보정을 위해 신청서나 부속서류를 돌려주지 않음 · 허가받은 사무원도 보정 가능, 등기소장은 보정명령을 감독"],["취하 시기·방법","취하는 등기를 마치거나 각하하기 전까지 가능 · 방문신청이면 등기소에 출석해 취하서를 내는 방법으로만 함, 구두 취하는 없음"],["취하 주체","공동신청한 등기는 쌍방이 함께 취하 · 일괄신청 중 일부 부동산만 취하 가능 · 임의대리인의 취하에는 특별수권 필요"]]},{"t":"table","title":"대리인과 판결에 의한 등기","head":["항목","내용"],"rows":[["대리 방식","당사자 한쪽이 상대방을 대리하거나 쌍방이 한 사람에게 위임 가능 · 비법무사가 보수 없이도 계속 반복하여 대리하면 위반(법무사법 제3조) · 쌍방 위임을 받은 법무사는 한쪽의 중지 요청을 거부할 의무"],["특별대리인","미성년자 자신의 채무를 위한 담보제공은 이해상반이 아님 · 미성년 자녀 2인의 공유물분할은 1인에 대해 특별대리인 필요"],["공동·단독 친권","공동친권자 중 한 명만 이해상반이면 다른 친권자와 특별대리인이 공동 대리 · 단독친권자가 사망해도 생존 부모의 친권은 당연히 부활하지 않음"],["판결 신청인","승소한 등기권리자나 승소한 등기의무자가 단독으로 신청 · 등기의무자가 신청할 때에는 자기 등기필정보를 제공 · 확정 후 10년이 지난 판결로도 신청 가능"],["단독신청 불가","공정증서·가처분결정으로는 단독신청 불가 · 상소심의 취소판결이나 재심판결만으로 종전 등기를 말소하지 못함"],["공유물분할 판결","공유물분할 판결은 형성력이 있어 변론종결 뒤 지분을 넘겨받은 제3자를 상대로 · 승계집행문을 받아 단독신청 가능 · 조정·화해권고결정에 의한 분할은 불가"],["허가서","판결서에 허가서 현존사실이 적혀 있어도 소유권이전등기에는 허가서를 냄"]]},{"t":"table","title":"등기필정보와 인감증명","head":["항목","내용"],"rows":[["등기필정보 제공 제외","관공서 촉탁과 승소한 등기권리자의 신청에는 등기필정보를 제공하지 않음 · 공유물분할로 취득한 자는 분할 전 지분의 등기필정보도 함께 냄"],["등기필정보 분실","분실해도 재발급하지 않으므로 등기의무자 본인의 출석 확인 · 변호사·법무사의 확인서면, 신청서 중 등기의무자 작성부분의 공증으로 대신(부동산등기법 제51조) · 공증은 본인이 출석해야 하고 법무사는 자기 사건의 확인서면을 쓰지 못함"],["등기필정보 작성 제외","채권자대위 등기와 승소한 등기의무자의 신청에는 등기필정보를 작성하지 않음 · 법정대리인이 신청하면 법정대리인에게 통지"],["인감증명 유효","인감증명은 발행일부터 3개월 이내의 것이어야 함(부동산등기규칙 제62조) · 소유권 외 권리의 명의인도 등기필정보 없이 등기관의 확인을 받으면 인감증명을 냄"],["재감자·협의분할서","재감자도 인감증명을 발급받을 수 있어 무인과 교도관 확인으로 대신하지 못함 · 공정증서인 협의분할서에는 상속인 전원의 인감증명 불필요"],["본인서명사실확인서","본인서명사실확인서는 서명한 신청서에 붙여 인감증명을 갈음 · 서명이 한자나 영문이어도 신청서의 성명은 한글로 적음"]]},{"t":"table","title":"허가·대위·촉탁·외국인","head":["항목","내용"],"rows":[["농지취득자격증명","농지취득자격증명은 상속·포괄유증·취득시효·공유물분할·진정명의회복 · 합의해제에 의한 말소와 가등기에는 불필요 · 국가·지방자치단체로부터 사거나 전용허가를 받은 농지를 사는 경우에는 필요"],["종중·토지거래허가","종중은 위토대장에 등재된 기존 위토가 아니면 농지를 취득하지 못함 · 토지거래허가구역 토지는 소유권 이전청구권 가등기에도 허가증 필요 · 가등기 때 허가증을 냈으면 본등기에는 다시 내지 않음"],["채권자대위 등기","금전채권자도 대위신청 가능, 무자력은 요건이 아님, 대위원인은 사서증서로 증명 가능 · 상속을 포기한 채무자를 대위해 상속등기 불가 · 대위 등기를 마치면 대위자와 피대위자에게 등기완료통지"],["관공서 촉탁","촉탁은 국가·지방자치단체가 하고 공사는 특별규정이 있을 때만 가능 · 관공서 촉탁은 대장과 등기기록이 맞지 않아도 수리 · 등기필정보와 인감증명 불필요"],["등록번호 부여","국가·지방자치단체·국제기관·외국정부의 등록번호는 국토교통부장관이 지정·고시 · 재외국민은 대법원 소재지 관할 등기소의 등기관, 법인은 주된 사무소 관할 등기관 · 법인 아닌 사단·재단은 시장·군수·구청장이 부여(부동산등기법 제49조)"],["외국 문서","외국 공문서는 아포스티유나 영사 확인을 받음 · 주한 외국공관이 공증한 문서와 신분증 원본은 예외 · 처분권한을 받은 대리인의 인감증명은 매도용일 필요 없음"]]}],"3":[{"t":"table","title":"소유권보존등기","head":["항목","내용"],"rows":[["보존등기 신청인","대장상 최초 소유자와 그 포괄승계인 · 확정판결로 소유권을 증명하는 자, 수용으로 취득한 자 · 건물에 한해 시장·군수·구청장의 확인으로 소유권을 증명하는 자(부동산등기법 제65조)"],["판결 보존등기 불가","건물은 대장상 소유자를 확정할 수 없더라도 · 국가나 건축허가명의인을 상대로 한 소유권확인판결로는 보존등기 불가 · 건축물대장이 없는 건물도 판결만으로 보존등기 불가"],["기록 사항","보존등기에는 등기원인과 그 연월일을 적지 않음"],["공유 보존등기","공유자 1인은 전원 명의의 보존등기를 신청 가능 · 자기 지분만의 보존등기는 불가 · 대장에 지분 표시 없이 공유로 등재되었으면 균등 지분으로 보존등기"],["보존등기 실무","대지에 제3자의 지상권이 있어도 그 말소나 승낙 없이 건물 보존등기 · 증축으로 기존 대장에 함께 오른 신축건물은 대장을 분리해야 독립건물로 보존등기 · 미등기 부동산에 가압류 촉탁이 오면 등기관이 직권으로 보존등기"]]},{"t":"table","title":"수용·협의취득에 의한 등기","head":["항목","내용"],"rows":[["수용 이전등기","사업시행자가 단독으로 신청(제99조) · 등기원인은 수용, 원인일자는 수용의 개시일 · 재결서등본이나 협의성립확인서와 보상금수령증 또는 공탁서 원본을 낸다, 등기필정보·검인은 필요 없다"],["수용 상속등기·말소","등기기록이 피상속인 명의이면 상속인에게 보상했어도 대위로 상속등기를 먼저 한다 · 수용의 개시일 뒤의 소유권이전등기는 직권말소하되 · 개시일 전 상속을 원인으로 한 것은 남긴다"],["수용 후 존속·실효","재결로 존속이 인정된 권리와 그 부동산을 위한 지역권도 남긴다 · 재결이 실효되면 공동신청으로 말소 · 직권말소된 등기를 직권으로 회복한다"],["사업인정 전 협의취득","사업인정 고시 전 협의취득은 사업시행자와 소유자가 공동으로 신청 · 취득협의서와 인감증명을 냄 · 미등기 토지면 대장상 소유명의인 앞으로 보존등기를 먼저 함"],["사업인정 후 협의","사업인정 고시 후 협의가 성립하면 협의성립확인서와 보상금수령증으로 단독신청 · 협의서만 내고 협의성립확인서가 없으면 수리하지 않는다"]]},{"t":"table","title":"공유물분할·합유등기","head":["항목","내용"],"rows":[["협의분할","협의분할은 공유자 전원이 참여해야 하지만 원래 지분비율과 다르게 나눌 수 있음 · 공유자가 아닌 자를 끼워 다른 필지까지 분할할 수는 없음 · 먼저 분필등기를 하고 분할 이전등기는 필지별로 따로 신청해도 됨"],["분할 효과","판결에 의한 분할은 확정으로, 조정에 의한 분할은 등기로 소유권이 바뀐다 · 농지라도 농지취득자격증명 불필요 · 甲 지분에 있던 근저당권은 乙 단독 소유가 된 필지에도 전사되어 효력이 있다"],["합유등기 기록","합유등기에는 지분을 기록하지 않는다 · 합유자 일부가 교체되면 처분한 합유자, 취득한 합유자, 남은 합유자 전원이 공동신청 · 처분자의 인감증명을 낸다"],["합유자 사망","합유자가 사망하면 지분은 상속되지 않고 잔존 합유자에게 귀속된다 · 2인 중 1인이 사망하면 잔존 합유자 단독소유로 변경등기를 한다"],["합유 변경 불가","합유를 곧바로 일부 공유·일부 합유로 바꾸는 변경등기는 불가 · 법인 아닌 사단 명의를 구성원 합유로 바꾸려면 소유권이전등기"]]},{"t":"table","title":"진정명의회복·환매특약·검인","head":["항목","내용"],"rows":[["진정명의회복 신청","자기 명의 등기가 있었거나 법률 규정으로 소유권을 취득한 자 · 대장상 소유자로서 보존등기를 할 수 있는 자 · 현 명의인과 공동으로 또는 판결로 진정명의회복 이전등기 신청, 등기원인일자는 적지 않음"],["진정명의회복 서류","토지거래허가증·농지취득자격증명은 불필요, 국민주택채권은 매입 · 공동신청이면 등기의무자의 인감증명 · 공유자 1인은 보존행위로 지분별 진정명의회복 이전등기를 단독 청구 가능"],["환매특약등기","매도인을 권리자, 매수인을 의무자로 소유권이전등기와 동시에 별개 신청서로 신청 · 매수인의 권리취득등기에 부기 · 환매권자는 매도인으로 한정"],["환매 불가 변경","일부 지분만의 환매 보류나 환매기간 연장 변경등기는 불가 · 환매특약등기에는 처분금지 효력이 없어 소유자는 제3자에게 매도 가능"],["환매권 행사","환매권 행사로 이전등기를 하면 등기관은 환매특약등기만 직권말소 · 그 사이 제3자의 소유권 외 권리는 공동신청으로 말소"],["검인","계약을 원인으로 한 소유권이전등기는 판결서·조정조서를 내더라도 검인을 받음 · 매각·공매, 수용, 가등기, 지방자치단체가 당사자인 계약, 토지거래허가증을 받은 경우에는 검인 불필요"],["거래가액","거래가액은 2006.1.1. 이후 작성된 매매계약서로 신청할 때 등기 · 원인증서가 판결이거나 가등기 신청이면 등기하지 않음 · 가등기에 의한 본등기에는 계약서를 내지 않아도 거래가액을 등기"]]}],"4":[{"t":"table","title":"지상권·구분지상권·지역권","head":["항목","내용"],"rows":[["지상권 기록사항","지상권의 필요적 기록사항은 설정의 목적과 범위 · 존속기간·지료와 지급시기는 약정이 있을 때만 기록(부동산등기법 제69조)"],["존속기간","존속기간을 최단기간보다 짧게 적어도 법정기간까지 늘어나므로 그대로 수리 · 100년 이상이나 철탑 존속기간 같은 불확정기간도 가능"],["설정 범위","토지 일부에는 도면을 붙여 설정 가능 · 공유지분만을 목적으로 하는 지상권은 불가 · 법정지상권 등기도 공동신청"],["구분지상권","구분지상권은 지하나 공중의 상하 범위를 정해 등기 · 범위가 다른 구분지상권 여러 개를 따로 등기 가능 · 건물 상층을 소유하기 위한 구분지상권, 수목 소유를 위한 구분지상권은 불가"],["구분지상권 변경","기존 구분지상권자의 승낙이 있으면 통상의 지상권도 설정 가능 · 통상 지상권을 구분지상권으로 바꾸는 변경은 이해관계인이 없거나 승낙이 있으면 부기로 함"],["재결 구분지상권","도시철도건설자 등이 재결로 취득한 구분지상권은 단독신청 · 먼저 된 강제경매로 매각되어도 말소하지 않음"],["지역권 신청","지역권은 승역지 관할 등기소에 신청 · 승역지에 등기하면 요역지에는 등기관이 직권으로 기록 · 요역지의 지상권자도 권리자 가능, 지역권자는 등기사항이 아님"]]},{"t":"table","title":"지역권 효과·전세권·임차권","head":["항목","내용"],"rows":[["지역권 이전·세금","요역지 소유권이 이전되면 지역권은 이전등기 없이 따라감 · 등록면허세 과세표준은 요역지의 시가표준액 · 대지권 등기가 된 토지에도 지역권 설정 가능"],["지역권과 합필","승역지에 하는 지역권 등기는 합필을 막지 않음 · 요역지지역권 등기가 있는 토지는 합필하지 못함(부동산등기법 제37조)"],["전세권 대상","농지에는 원칙적으로 전세권을 설정하지 못함 · 공유지분만을 목적으로 하는 전세권도 불가 · 건물 일부에는 도면을 붙여 설정, 특정층 전부면 도면 불필요"],["건물 일부 전세권","건물 일부 전세권자도 건물 전부의 매각대금에서 우선변제 · 다른 층의 후순위 전세권자는 존속기간 연장의 이해관계인"],["전세권 변경","전세금 감액은 승낙 없이 부기로 · 존속기간 연장은 승낙이 없으면 주등기로 · 법정갱신된 전세권을 이전하거나 변경하려면 먼저 법정갱신 변경등기"],["임차권등기명령","미등기 건물에 임차권등기명령 촉탁이 오면 등기관이 직권으로 보존등기를 한 뒤 임차권등기 · 결정 후 소유권이 이전되었는데 전 소유자를 의무자로 촉탁하면 각하 · 같은 사람 명의의 전세권등기가 있어도 촉탁은 수리"],["임차권 이전·공유","존속기간이 끝난 임차권과 임차권등기명령에 따른 임차권등기에는 이전·전대등기 불가 · 공유 부동산의 임차권은 공유자 전원이 의무자 · 매출 비율에 따른 가변 차임도 등기 가능"]]},{"t":"table","title":"근저당권 설정·변경","head":["항목","내용"],"rows":[["설정 최고액","채권자나 채무자가 여럿이어도 단일한 채권최고액만 기록 · 채권자별·채무자별로 나누어 적지 못함 · 하나의 계약을 두 개의 동순위 근저당권으로 나누어 등기할 수도 없음"],["채무자 표시","연대채무자도 단순히 채무자로 적음 · 외국통화 최고액은 외화로 기록 · 설정계약서에는 채무자 표시만 있으면 되고 채무자 날인은 불필요"],["채무자 변경","채무자 변경등기는 근저당권자가 권리자, 설정자가 의무자로 공동신청하고 설정자의 등기필정보를 냄 · 채무자는 당사자가 아니어서 동의서 불필요 · 채무자 표시변경에는 인감증명·등기필정보 불필요"],["최고액 변경","채권최고액 증액은 후순위권리자나 압류권자의 승낙이 없으면 주등기 · 감액은 설정자가 권리자가 되며 근저당권부 채권의 질권자·가압류권자의 승낙 필요 · 공동근저당의 최고액을 부동산별로 쪼개는 변경등기는 불가"]]},{"t":"table","title":"근저당권 이전·공동저당","head":["항목","내용"],"rows":[["확정 전 이전","피담보채권 확정 전에는 계약양도·계약의 일부양도·계약가입을 원인으로 이전 · 채권양도나 대위변제를 원인으로는 이전 불가 · 확정 전 계약양도의 이전계약서에는 채무자가 표시·날인"],["확정 후 이전","확정 후에는 확정채권 양도나 확정채권 대위변제로 이전, 대위변제면 대위변제증서만 냄 · 채권양도 통지서나 채무자 승낙서, 물상보증인·제3취득자의 승낙은 불필요 · 저당권 이전등기는 언제나 부기"],["공동근저당","공동근저당은 같은 채권을 담보하면 되고 소유권과 지상권의 주체가 달라도 됨 · 추가설정에는 종전 부동산의 등기필정보 불필요 · 채무자 주소가 다르면 변경등기를 먼저 함"],["대위등기·공장저당","공동저당 대위등기는 선순위자가 의무자, 차순위자가 권리자로 공동신청하고 배당표를 냄 · 공장저당의 기계·기구는 토지·건물 소유자의 것이어야 함 · 목록 변경은 소유자가 단독신청, 일부 멸실·분리면 저당권자 동의서"]]}],"5":[{"t":"table","title":"경정등기","head":["항목","내용"],"rows":[["경정등기의 요건","경정등기는 등기할 때부터 있던 착오나 빠진 부분을 바로잡는 등기이고, 등기 완료 뒤 생긴 사유로는 못 한다 · 소유권을 저당권으로 바꾸는 것처럼 권리 자체를 경정하거나 甲·乙 공유를 丙·丁 공유로 바꾸는 경정은 안 된다 · 법정상속분 등기와 협의분할 등기 사이의 경정은 같은 상속인끼리라 동일성이 있어 할 수 있다 · 판례는 동일성이 없더라도 따로 보존등기가 없고 손해 볼 이해관계인이 없으면 경정을 허용한다"],["명의인표시 경정","등기명의인표시 경정은 인격의 동일성이 유지될 때만 할 수 있어 법인 아닌 사단을 법인으로, ‘국 관리청 OO군’을 ‘OO군’으로 바꾸는 경정은 안 된다 · 현재 명의인이 아닌 종전 명의인이나 사망자에 대한 표시경정도 받지 않는다 · 동일성을 해치는 표시경정이 잘못 수리되었으면 종전 명의인으로의 회복은 현재 명의인이 단독으로 하거나 종전 명의인과 공동으로 하고, 종전 명의인 혼자서는 못 한다 · 부동산표시 경정은 명의인 1인도 단독으로 신청한다"],["일부말소 의미의 경정","甲 단독소유를 甲·乙 공유로 바꾸는 것처럼 실질이 일부말소인 경정은 이해관계 있는 제3자의 승낙이 있으면 부기로 하고, 승낙이 없으면 주등기로 하지 않고 수리하지 않는다 · 일반 경정등기는 승낙이 없으면 주등기로 한다 · 경정으로 없어지는 지분만을 목적으로 한 제3자의 등기는 등기관이 직권말소하고, 그것이 가압류·가처분이면 집행법원에 통지한다 · 소유권 경정에는 소유권이 줄어드는 자의 인감증명을 낸다"],["등기명의인표시 변경","소유권이전등기를 할 때 주소증명정보로 등기의무자의 주소 변경이 명백하면 등기관이 직권으로 표시변경등기를 하고, 법인 본점 이전도 같다 · 개명이나 도로명주소로의 변경만 있는 경우는 직권으로 하지 않는다 · 주소가 여러 번 바뀌었으면 최종 주소로 한 번에 변경한다 · 저당권 말소에는 변경 사실을 증명하면 표시변경을 생략할 수 있다 · 촉탁으로 된 가압류·임차권등기도 명의인이 표시변경을 신청하고, 유한회사의 주식회사 조직변경은 표시변경으로 한다"]]},{"t":"table","title":"말소등기","head":["항목","내용"],"rows":[["이해관계 있는 제3자","말소에 이해관계 있는 제3자가 있으면 승낙이 있어야 하고, 말소할 때 그 제3자 명의 등기는 등기관이 직권말소한다 · 소유권보존등기를 말소할 때 그 위의 근저당권자, 말소할 소유권이전등기보다 앞선 근저당권에 기한 경매의 신청채권자, 같은 피보전권리를 가진 선행 가처분채권자는 이해관계인이다 · 변론종결 뒤의 승계인은 판결의 효력이 직접 미치므로 이해관계인이 아니다 · 증여 해제를 원인으로 새 이전등기를 할 때의 압류권자도 승낙이 필요 없다"],["말소등기의 신청인","근저당권 설정 후 소유권이 넘어가면 설정자와 제3취득자 모두 근저당권자와 공동으로 말소를 신청할 수 있다 · 근저당권 양수인은 설정자와 공동으로 말소하고, 합병 전에 말소 원인이 생겼으면 이전등기 없이 승계 법인이 말소한다 · 근저당권자가 소재불명이면 공시최고 후 제권판결로 소유자가 단독 말소한다 · 혼동으로 소멸한 근저당권도 제3자에게 소유권이 넘어간 뒤에는 현 소유자와 근저당권자가 공동으로 말소한다 · 사망자 명의 등기는 상속인 전원을 상대로 말소한다"]]},{"t":"table","title":"말소회복등기","head":["항목","내용"],"rows":[["말소회복등기","부적법하게 말소된 등기를 말소 당시로 소급해 되살리는 등기이고, 당사자가 자발적으로 말소한 경우는 회복하지 못한다 · 신청으로 말소된 것은 신청으로, 촉탁은 촉탁으로, 직권 말소는 직권으로 회복한다 · 전부 회복이면 종전과 같은 순위번호를 쓴다 · 보존등기나 가등기를 명의인이 단독 말소했으면 단독으로 회복하고, 회복청구의 상대방은 말소 당시의 소유자이다 · 위조 서류로 말소되었더라도 실체관계에 부합하면 회복을 청구하지 못한다"],["회복등기의 이해관계인","근저당권 회복에서는 말소 뒤 소유권을 넘겨받은 현 소유자와, 말소 전부터 있던 후순위 근저당권자도 이해관계인이다 · 가등기 회복에서는 말소 뒤 가처분이나 이전등기를 받은 제3자가 이해관계인이고 선의·악의와 관계없이 승낙의무가 있다 · 소유권이전등기 회복에서 말소 뒤 같은 전 소유자에게서 이전받은 자는 회복과 양립할 수 없어 이해관계인이 아니다 · 가처분채무자의 상속인도 이해관계인이 아니다"]]}],"6":[{"t":"table","title":"가등기","head":["항목","내용"],"rows":[["가등기의 대상·신청","가등기는 권리의 설정·이전·변경·소멸 청구권을 보전하려 할 때 하고, 시기부·정지조건부나 장래에 확정될 청구권도 된다(부동산등기법 제88조) · 사인증여로 생긴 이전청구권도 가등기할 수 있지만 부동산표시나 명의인표시 변경을 위한 가등기는 없다 · 가등기의무자의 승낙이 있거나 가등기가처분명령이 있으면 가등기권리자가 단독으로 신청하고(제89조), 가등기가처분명령에 따른 가등기를 법원이 촉탁하면 각하한다 · 가등기명의인은 단독으로 말소를 신청할 수 있다"],["본등기와 등기의무자","본등기의 순위는 가등기의 순위에 따른다(제91조) · 가등기 후 제3자에게 소유권이 넘어갔어도 본등기의 의무자는 가등기 당시의 소유자이다 · 가등기권리자가 본등기 대신 별도로 소유권을 이전받아도 가등기는 혼동으로 소멸하지 않으므로 중간 처분제한을 이기려면 다시 본등기를 할 수 있다 · 담보가등기의 본등기에는 청산금 통지 도달과 지급·공탁을 증명하는 정보를 낸다 · 형식상 매매예약이라도 요구하면 본등기를 해 주기로 했으면 완결권 행사 없이 본등기를 신청한다"],["본등기 후 직권말소","소유권이전 본등기를 하면 가등기 후 본등기 전의 등기는 원칙적으로 직권말소한다 · 해당 가등기상 권리를 목적으로 한 가압류·가처분, 가등기 전 가압류에 의한 강제경매개시결정, 가등기 전 담보가등기·전세권·저당권에 의한 임의경매개시결정, 가등기권자에게 대항할 수 있는 주택·상가 임차권등기는 남긴다(부동산등기규칙 제147조) · 체납처분 압류등기는 직권말소대상통지를 하고 이의를 검토한다"],["용익권·담보권 가등기의 본등기","지상권·전세권·임차권 설정 가등기로 본등기를 하면 가등기 후 같은 부분에 된 지상권·지역권·전세권·임차권 설정등기만 직권말소하고(제148조), 저당권설정등기는 남긴다 · 저당권설정 가등기로 본등기를 하면 중간 등기를 직권말소하지 않는다 · 공유자 일부 지분의 이전청구권 가등기 후 토지 전부에 된 지상권은 본등기 때 전부 말소한다"]]},{"t":"table","title":"처분금지가처분","head":["항목","내용"],"rows":[["처분금지가처분 등기","1필지의 특정 일부에는 가처분등기를 못 하므로 그 부분의 청구권 보전을 위한 토지 전부의 가처분 촉탁은 수리한다 · 소유권 외 권리의 설정청구권 가처분이라도 채무자가 소유명의인이면 갑구에 한다 · 가등기상 권리의 처분금지 가처분은 되지만 본등기를 금지하는 가처분은 안 된다 · 상속관계를 표시해 촉탁하면 상속등기 없이 가처분등기를 할 수 있다 · 부동산별로 채권자가 다르면 결정이 하나여도 따로 촉탁한다"],["가처분채권자의 말소신청","가처분채권자가 가처분채무자를 의무자로 이전·말소·설정등기를 신청할 때 가처분 이후의 침해 등기를 단독으로 말소 신청할 수 있다(제94조) · 지상권·전세권·임차권 설정 가처분은 같은 부분의 용익권만 말소하고 저당권은 말소하지 못한다 · 동시에 말소하지 않았더라도 가처분에 기한 것이라는 소명자료로 나중에 신청할 수 있고, 채무자와 공동신청한 경우에는 이 말소신청을 못 한다 · 이후 등기를 말소하거나 이전등기만 할 때에도 가처분등기는 등기관이 직권말소한다"]]},{"t":"table","title":"가압류·경매·회생 관련 등기","head":["항목","내용"],"rows":[["가압류·경매 등기","가압류 채권자가 여럿이면 선정당사자라도 전원을 기록하고, ‘외 ○인’으로 된 등기에 일부 해제 촉탁이 오면 먼저 경정하고 변경한다 · 청구금액 경정에는 뒤 권리자의 승낙이 필요 없다 · 등기된 이전청구권 가등기에만 부기로 가압류할 수 있고, 합유지분 가압류는 각하하며 이미 된 것은 직권말소한다 · 본압류로 이행된 가압류만의 말소 촉탁은 각하한다 · 가압류 후 소유자가 바뀌어도 가압류 당시 소유자를 의무자로 한 경매 촉탁을 수리하고, 임의경매 촉탁도 소유자 변동과 관계없이 수리한다"],["매각에 따른 촉탁","매각으로 인한 이전등기에는 농지취득자격증명·토지거래허가증이 필요 없다 · 경매개시결정등기의 말소는 매각 이전등기 촉탁과 함께 하고, 매수인이 종전 소유자여도 매각을 원인으로 이전등기를 한다 · 일부 공유자가 매수인이면 그 지분을 뺀 나머지만 이전한다 · 말소할 부담이 부기등기로 되어 있으면 주등기만 말소 촉탁한다 · 최선순위 담보권보다 뒤인 가등기는 말소되고, 보증금을 다 받지 못한 대항력 있는 주택임차권은 말소하지 않는다"],["회생·파산·몰수보전","회생 보전처분등기가 있어도 가압류·경매·체납처분 압류 촉탁은 수리한다 · 회생절차개시 등기가 있는 부동산에 파산선고나 다른 회생개시 촉탁이 오면 각하한다 · 부인등기는 부인권자가 단독신청하고 등록면허세를 면제하며 그 뒤 부인된 명의인을 의무자로 한 신청은 각하한다 · 회생계획에 따른 처분에는 인가결정 등본을 붙인다 · 몰수보전등기 뒤의 이전등기 신청은 각하하지 않고, 추징보전등기는 ‘가압류’를 목적으로 검사의 신청에 따라 법원이 촉탁한다"]]}],"7":[{"t":"table","title":"표시변경과 합필","head":["항목","내용"],"rows":[["표시변경 신청의무","토지의 분할·합병이나 표제부 사항의 변경이 있으면 소유권 명의인이 1개월 이내에 등기를 신청한다(부동산등기법 제35조) · 건물 분할·멸실도 1개월 이내이고, 게을리해도 과태료는 없다 · 행정구역이나 그 명칭이 바뀌면 등기관이 직권으로 표시변경을 한다 · 지적소관청의 불일치 통지 뒤 1개월 안에 신청이 없으면 등기관이 직권으로 변경한다 · 표시변경은 주등기로 하고 표제부에 접수연월일을 적는다"],["합필 제한","소유권·지상권·전세권·임차권·승역지 지역권 등기와, 모든 토지에 있는 원인·연월일·접수번호가 같은 저당권 등기 외의 권리 등기가 있으면 합필하지 못한다(제37조) · 그래서 요역지지역권·환매특약·가압류·가처분이 있으면 모든 토지에 같은 내용이어도 합필이 안 된다 · 추가 설정된 저당권은 접수번호가 달라 안 되고, 한 토지는 전부, 다른 토지는 일부 지분을 목적으로 한 저당권도 안 된다 · 전세권과 임차권처럼 종류가 달라도 허용 목록 안이면 합필할 수 있다"],["합필의 특례","대장상 합병 뒤 합필등기 전에 어느 토지의 소유권이 이전되거나 제한사유 등기가 생겼어도 이해관계인의 승낙이 있으면 합필 후 토지를 공유로 하거나 권리의 목적을 지분으로 하는 합필등기를 할 수 있다(제38조) · 요역지지역권이 있으면 합필 후 토지 전체를 위한 지역권으로 신청한다 · 이 특례는 토지에만 있고 건물 합병에는 없다 · 지분 비율이 서로 다른 공유 토지는 합병하지 못한다"],["건물 멸실등기","멸실한 건물의 명의인이 1개월 안에 멸실등기를 하지 않으면 대지 소유자가 대위하여 신청한다(제43조) · 건물이 처음부터 없으면 명의인이 지체 없이 신청하고, 대지 소유자는 1개월을 기다리지 않고 대위할 수 있다 · 대장에 멸실이 기록되어 있으면 근저당권자의 승낙이 필요 없다 · 구분건물 멸실이면 등기기록을 폐쇄하지 않고, 1동 전부가 멸실되면 한 구분소유자가 다른 구분소유자를 대위해 신청할 수 있다"]]},{"t":"table","title":"대지사용권과 대지권","head":["항목","내용"],"rows":[["대지사용권과 대지권","대지사용권은 전유부분을 소유하기 위해 대지에 가지는 권리로, 등기되지 않은 권리여도 되고 소유권 외에 지상권·전세권·임차권도 된다 · 그중 분리처분할 수 있다고 정하지 않은 것이 대지권이다 · 지목이 ‘대’가 아닌 잡종지도 대지권의 목적이 될 수 있다 · 대지권 비율은 대지 공유지분과 같아야 하고, 둘 이상의 전유부분을 가진 자의 처분 비율은 규약이 없으면 전유부분 면적비율에 따른다 · 다른 위탁자로부터 따로 신탁된 토지와 건물은 수탁자가 같아도 대지권등기를 못 한다"],["대지권등기 실행","건물에 대지권등기를 하면 등기관이 직권으로 토지 등기기록에 대지권이라는 뜻을 기록하고, 토지가 다른 등기소 관할이면 그 등기소가 기록한다 · 토지에 소유권이전·보존 외의 소유권 등기나 다른 권리 등기가 있으면 전유부분 표제부에 ‘별도의 등기가 있다’는 뜻을 적고, 전제된 등기가 말소되면 등기관이 그 기록도 지운다 · 대지권 변경·소멸 등기는 한 구분소유자가 다른 구분소유자를 대위해 신청할 수 있다"],["분리처분 금지","대지권이라는 뜻의 등기가 된 토지에는 소유권이전 가등기, 저당권설정 가등기, 토지만의 가압류를 하지 못하고, 토지만을 목적으로 한 지상권도 설정하지 못한다 · 전유부분에 전세권이나 임차권을 설정하는 것은 허용된다 · 대지 저당권이 있는 상태에서 구분건물을 추가 담보로 할 때에는 건물과 대지권을 일체로 신청한다 · 임차권이 대지권이면 공동저당이 안 되므로 건물만 저당권을 설정하고 그 뜻을 부기한다"]]},{"t":"table","title":"구분건물 표시등기와 공용부분","head":["항목","내용"],"rows":[["구분건물 표시등기","구분건물 일부만 보존등기를 할 때에는 나머지 구분건물의 표시등기를 동시에 신청하고 다른 소유자를 대위할 수 있다 · 비구분건물에 접속해 구분건물을 신축하면 기존 건물을 구분건물로 바꾸는 표시변경을 동시에 신청한다 · 한 층의 구획을 세로에서 가로로 바꾸면 면적이 같아도 동일성이 없어 표시변경을 못 한다 · 공용부분이 전유부분에 편입되어 면적이 늘어도 대지권비율은 그대로이다"],["규약상 공용부분","공용부분이라는 뜻의 등기는 그 건물의 소유명의인이 단독으로 신청하고 표제부에 기록하며 각 구의 권리 등기는 말소하는 표시를 한다 · 미등기 건물은 보존등기를 먼저 해야 하고, 소유권 외 권리가 있으면 그 명의인의 승낙을 낸다 · 공용부분의 득실변경에는 등기가 필요 없다 · 규약을 폐지하면 공용부분의 취득자는 지체 없이 소유권보존등기를 신청한다(제47조)"]]}],"8":[{"t":"table","title":"상속등기","head":["항목","내용"],"rows":[["상속등기 신청","상속등기는 상속인이 단독으로 신청하고, 공동상속이면 상속분이 같아도 상속인별 지분을 반드시 적는다 · 자녀 전부가 포기하면 배우자가 단독상속인이 되고, 포기한 자가 있으면 가정법원의 상속포기신고 수리증명을 낸다 · 상속등기 전에 상속인 중 한 명이 사망했으면 상속개시일자를 순차로 적어 1건으로 신청할 수 있다 · 상속인의 채권자는 한정승인·포기 기간 중에도 대위로 상속등기를 할 수 있다 · 상속·유증 등기는 관할 아닌 등기소에도 신청할 수 있으나, 관공서가 압류·수용 촉탁에 붙여 하는 대위 상속등기는 그렇지 않다"],["협의분할·경정","친권자와 미성년 자녀가 공동상속인이면 친권자가 아무것도 취득하지 않아도 특별대리인이 필요하고, 자녀가 여럿이면 자녀마다 선임한다 · 법정상속등기와 협의분할 등기는 서로 경정할 수 있고, 재협의분할의 원인일자는 재협의일이다 · 재협의로 상속인 전부가 바뀌면 경정을 못 하고, 상속등기 뒤 지분이 경매나 매매로 넘어간 경우도 경정을 못 한다 · 지분이 줄어드는 상속인의 지분에 가압류가 있으면 그 권리자의 승낙이 필요하다 · 상속재산분할심판이 확정되면 법정상속등기 없이 바로 심판대로 등기한다"],["유증 등기","유증은 포괄·특정 모두 상속등기 없이 유증자에서 수증자로 바로 이전하고, 이미 상속등기가 되었으면 말소하지 않고 상속인에게서 이전한다 · 수증자가 권리자, 유언집행자(여럿이면 과반수)가 의무자로 공동신청하고 유증자의 등기필정보를 낸다 · 미등기 부동산이면 포괄수증자는 직접 보존등기를 할 수 있으나 특정수증자는 상속인 명의 보존등기 뒤 이전받는다 · 등기관은 유류분 침해 여부를 심사하지 않는다 · 유증 가등기는 유언자 사망 뒤에만 받는다"]]},{"t":"table","title":"신탁등기","head":["항목","내용"],"rows":[["신탁등기 신청","신탁등기는 신탁을 원인으로 한 소유권이전등기와 1건의 신청정보로 일괄 신청하고, 처분이나 신탁 종료로 인한 이전등기와 신탁등기 말소도 일괄한다 · 위탁자가 여럿이어도 수탁자·부동산·신탁목적이 같으면 일괄할 수 있다 · 위탁자의 선언에 의한 신탁은 공익신탁이 아니면 공정증서를 낸다 · 신탁업 인가 없는 영리회사는 수탁자가 될 수 없다 · 재신탁에는 위탁자가 아니라 수익자의 동의가 필요하고, 조합원 전원의 동의를 수익자집회 결의로 갈음하지 못한다"],["수탁자 변경·신탁재산 심사","수탁자의 사망·파산 등으로 새 수탁자가 선임되면 새 수탁자가 단독으로 이전등기를 하고, 사임·자격상실 등이면 새 수탁자와 종전 수탁자가 공동신청한다 · 여러 수탁자 중 1인이 사임 등으로 물러나면 나머지 수탁자와 물러난 수탁자가 공동으로 합유명의인 변경등기를 하고, 신탁원부는 등기관이 직권으로 바꾼다 · 수익자변경권이 유보되어 있으면 종전 수익자의 승낙이 필요 없다 · 수탁자를 의무자로 한 신청이 신탁목적에 반하면 위탁자의 승낙서가 있어도 각하하지만 수탁자를 의무자로 한 처분제한·경매 촉탁은 수리한다"]]},{"t":"table","title":"법인 관련 등기","head":["항목","내용"],"rows":[["법인의 합병·분할","합병으로 소멸한 회사 명의의 부동산은 표시변경이 아니라 소유권이전등기로 존속·신설회사에 넘긴다 · 순차 흡수합병이면 최초 회사에서 최종 회사로 바로 이전할 수 있지만 합병 뒤 분할로 넘길 재산은 합병 이전등기를 먼저 한다 · 상호 변경 뒤 합병되었으면 표시변경 없이 바로 합병 이전등기를 한다 · 대표이사가 위임 뒤 바뀌어도 자격자대리인의 대리권은 소멸하지 않는다 · 회사분할에 의한 이전에는 토지거래허가증이 필요 없다"],["청산법인","청산종결등기가 되었어도 청산사무가 남았으면 등기당사자능력이 있다 · 등기기록이 폐쇄되지 않았으면 청산인 등기가 된 법인등기사항증명서와 법인인감을 낸다 · 폐쇄된 경우 청산법인이 등기권리자이면 등기기록을 부활하고, 등기의무자이면서 청산인 등기가 되어 있으면 부활 없이 폐쇄된 등기사항증명서와 청산인의 개인인감으로 신청할 수 있다 · 청산인 등기 없이 폐쇄되었으면 부활해 청산인 등기를 한 뒤 법인인감을 낸다"],["법인 아닌 사단·재단","법인 아닌 사단·재단의 등기는 그 명의로 대표자나 관리인이 신청하고, 대표자의 성명·주소·주민등록번호가 등기사항이다 · 대표자 증명서면과 사원총회결의서에는 성년자 2인의 확인과 인감증명을 붙이되 법무사·변호사가 대리하면 그 확인으로 갈음한다 · 등록번호대장은 대표자 증명서면이 아니다 · 처분에는 사원총회 결의서가 필요하나 정관에 다른 정함이 있으면 그에 따른다 · 근저당권 채무자인 사단은 등록번호나 대표자를 등기하지 않는다"],["허가가 필요한 처분","민법상 재단법인의 기본재산을 매매·증여 등으로 처분하면 주무관청의 허가서를 내고 정관·이사회의사록은 필요 없으며 지상권 같은 제한물권 설정에는 허가가 필요 없다 · 학교법인 기본재산은 담보 제공 때 허가를 받았으면 경매 매각에 다시 허가가 필요 없고, 교지·교사는 허가가 있어도 처분할 수 없다 · 전통사찰 보존지의 양도·증여에는 문화체육관광부장관, 담보 제공에는 시·도지사의 허가가 필요하고, 시효취득은 허가 대상이 아니다"]]}],"9":[{"t":"table","title":"등기관 처분에 대한 이의","head":["항목","내용"],"rows":[["이의신청의 관할·방법","등기관의 결정이나 처분에 이의가 있으면 그 등기관이 속한 지방법원에 이의신청을 하고(부동산등기법 제100조), 신청은 그 등기소에 이의신청서를 내거나 전산정보처리조직으로 보내는 방법으로 하며 구술로는 못 한다(제101조) · 새로운 사실이나 증거로는 이의하지 못하고, 판단 기준은 결정·처분 당시의 자료이다 · 이의에는 집행정지 효력이 없고 기간 제한도 없다 · 등기관이 이유 없다고 보면 3일 이내에 의견을 붙여 법원에 보낸다"],["이의신청을 할 수 있는 자","각하결정에는 등기신청인인 등기권리자와 등기의무자만 이의할 수 있고 제3자는 못 한다 · 등기를 마친 처분에는 등기상 이해관계인이 이의할 수 있으며 채무자의 신청으로 대위등기가 말소되면 대위한 채권자가 이의할 수 있다 · 말소에 필요한 제3자 승낙서가 없었다는 사유로 말소등기의무자가 이의하지는 못하고, 저당권설정자는 저당권 이전의 부기등기에 이의하지 못한다"],["이의 결과와 기록명령","이미 마친 등기에 대한 이의는 제29조 제1호·제2호 사유일 때만 제58조 절차로 직권말소하고, 제3호 이하 사유면 직권말소하지 못하고 법원에 보낸다 · 신청권한 없는 자의 등기라도 이의로 말소를 구할 수는 없다 · 법원의 기록명령에 대한 항고에도 집행정지 효력이 없어 등기관은 기록명령대로 등기한다 · 기록명령 전에 제3자에게 권리이전등기가 되었거나 첨부정보 제출 명령에 응하지 않으면 기록명령에 따른 등기를 하지 못한다"],["각하와 보정","등기관이 보정을 명한 날의 다음 날까지 보정하지 않으면 각하하고, 각하결정을 한 뒤에는 고지 전에 보정되어도 효력이 그대로이다 · 등기할 것이 아닌 등기가 이미 되었으면 제58조의 통지·이의 절차를 거쳐 직권말소한다 · 각하결정 등본과 함께 신청서를 뺀 첨부서류를 돌려준다 · 각하되면 수수료를 돌려주지 않고 취하하면 환급한다 · 포괄승계인의 신청이나 주소 변경이 증명되는 경우는 의무자 표시 불일치로 각하하지 않지만 외국인·법인 아닌 사단과 주민등록번호가 기록되지 않은 경우에는 이 특례가 없다"]]},{"t":"table","title":"전자신청과 수수료","head":["항목","내용"],"rows":[["전자신청","전자신청은 당사자가 직접 하거나 변호사·법무사가 대리하고, 외국인 자격자대리인도 대리할 수 있다 · 법인 아닌 사단·재단은 직접 전자신청을 못 한다 · 최초 신청 전에 등기소에 직접 출석해 사용자등록을 하고, 유효기간은 3년이며 만료 3개월 전부터 연장할 수 있다 · 법인은 전자증명서 이용등록으로 사용자등록을 갈음한다 · 전자신청의 취하는 전산정보처리조직으로만 하고, 각하 고지는 전자우편으로 할 수 있으며 보정 통지는 구두·전화로도 된다"],["등기신청수수료·세금","부동산의 분할·구분·합병·멸실과 표시변경·경정등기는 대지권 등기 외에는 수수료가 없다 · 신탁등기는 소유권이전등기와 별도로 수수료를 낸다 · 국가가 공권력 주체로서 한 국세압류등기의 말소 촉탁은 면제되지만 납세담보 저당권의 말소 촉탁은 면제되지 않는다 · 회생·파산 관련 법원사무관의 촉탁은 등록면허세와 수수료가 면제된다 · 대위 보존등기는 채권자가 세금을 내고 국민주택채권도 사며, 처분제한 촉탁에 따른 직권 보존등기에는 채권 매입이 없다"]]},{"t":"table","title":"정비사업·환지·금지사항 부기","head":["항목","내용"],"rows":[["정비사업 이전고시 등기","이전고시 통지 뒤에는 대지·건축물 등기가 될 때까지 종전 토지에 권리 등기뿐 아니라 표시 등기도 못 하고, 위반한 등기는 제58조로 직권말소한다 · 시행자는 표시변경 등을 대위하여 원인이나 목적이 달라도 일괄 신청할 수 있다 · 등기관은 관리처분계획·이전고시 서면과의 일치만 심사하고 종전 등기기록과의 일치는 심사하지 않는다 · 구분건물 보존등기는 1동 전부를 한 신청서로 하고, 담보권 등기는 보존등기와 접수번호를 따로 받는다"],["환지·토지개발 등기","환지계획인가 고시(농어촌정비법)나 환지처분 공고(도시개발법) 뒤에는 종전 토지에 다른 등기를 못 하고 경매개시결정 예외도 없다 · 환지등기 촉탁은 사업지역 토지 전부에 대해 동시에 하고, 공유토지를 각 단독소유로 환지한 경우는 환지등기를 못 한다 · 시행자는 원인이나 목적이 달라도 대위등기를 일괄 촉탁할 수 있다 · 토지개발등기에서는 종전 토지 말소와 새 토지 보존을 동시에 일괄 신청하고, 같은 신탁등기·금지사항 부기는 함께 일괄하되 저당권은 따로 신청하며 국민주택채권은 사지 않는다"],["금지사항 부기·관리청","주택법상 금지사항 부기등기는 공동사업주체가 합유로 등기한 경우에도 할 수 있다 · 보조금법상 금지사항은 이미 저당권 등이 있으면 주등기로 한다 · 한국주택금융공사 금지사항 부기가 있어도 이전청구권 가등기에는 공사의 동의가 필요 없고, 매각으로 인수되지 않으면 함께 말소 촉탁한다 · 토지보상법상 환매권은 등기하지 못한다 · 조선총독부 명의 부동산은 명의인표시변경으로, 이왕직 명의 부동산은 소유권이전등기로 ‘국’ 명의로 바꾼다"]]}],"10":[{"t":"table","title":"공탁당사자와 관할","head":["항목","내용"],"rows":[["공탁 당사자능력","공탁법에는 당사자능력·행위능력에 관한 일반 규정이 없어 민법·민사소송법에 따른다 · 대표자 정함이 있는 법인 아닌 사단·재단, 청산종결등기 뒤 잔존사무가 있는 회사도 당사자능력이 있다"],["미성년·피공탁자","미성년자는 권리만 얻는 범위에서 공탁행위능력이 있지만 출급청구는 법정대리인의 동의나 대리로 한다 · 피공탁자는 공탁서 기재로 형식적으로 정해진다 · 사망자를 피공탁자로 한 수용보상금 공탁은 상속인들에 대한 공탁으로 유효하다"],["변제공탁자","연대채무자·보증인·물상보증인·제3취득자는 채무자의 의사에 반해서도 변제공탁을 할 수 있다"],["변제공탁 관할","변제공탁은 채무이행지의 공탁소에 한다 · 지참채무는 채권자(상속인이면 각 상속인) 주소지, 추심채무는 채무자 주소지나 영업소 소재지이다 · 예금채무는 추심채무로 보아 은행 영업소 소재지 관할이다"],["관할 예외·잘못","국내에 주소가 없는 외국인·재외국민을 위한 지참채무 공탁은 서울중앙지방법원 공탁관에게 할 수 있다 · 관할 없는 공탁소에 한 변제공탁은 수리되어도 무효이고 착오로 회수할 수 있다 · 피공탁자가 수락하거나 출급하면 유효해지고 수용보상금은 토지 소재지 공탁소에도 공탁할 수 있다"],["관할 외 공탁소 처리","금전변제공탁 신청과 금전공탁의 지급청구에만 적용한다 · 재판상 담보공탁·집행공탁·수용보상금 공탁에는 적용하지 않는다"],["관할 외 공탁소 요건","접수공탁소와 관할공탁소가 모두 지방법원 본원이나 지원이어야 하고 시·군법원은 빠진다 · 두 공탁소가 같은 특별시·광역시에 있으면 적용하지 않는다 · 공탁금은 가상계좌로 납입하는 것이 원칙이다"]]},{"t":"table","title":"공탁 신청과 공탁관의 처분","head":["항목","내용"],"rows":[["시·군법원 공탁관","시·군법원 공탁관은 소액사건 등에 관한 변제공탁을 받지만 집행공탁은 못 받는다"],["공탁 신청 방식","공탁은 공탁관에게 출석해 신청하고 우편으로는 못 한다 · 법인 아닌 사단은 정관·규약과 대표자 자격 증명서면을 붙인다 · 판결문에 대표자가 나와 있어도 생략하지 못하며 종중등록증명서는 대표자 증명서면이 아니다"],["첨부서면 기한","관공서 발급 서면은 3개월 이내의 것이어야 한다 · 재결서·판결문의 주소 표시는 주소 소명서면이 되지 못한다 · 주소불명이면 최종주소와 미거주 소명자료를 내고, 동시 여러 건 공탁의 같은 첨부서면은 1건에만 붙인다"],["공탁관 심사","공탁관은 신청서와 첨부서면만으로 형식적으로 심사하되 그 범위에서 실체 요건도 본다 · 특약이 없는데 말소서류 교부를 반대급부로 붙인 공탁도 수리할 수밖에 없다 · 전부명령의 유효 여부도 심사하지 않는다"],["불수리·성립 시기","신청인이 보정·취하 권유에 응하지 않아도 접수를 거절하지 못하고 이유를 적은 불수리결정을 한다 · 결정서에는 공탁관 인감도장을 찍는다 · 공탁 성립 시기는 수리 때가 아니라 공탁물을 납입한 때이다"],["공탁관 처분 이의","이의신청 대상은 공탁관의 불수리처분이고 관할 지방법원에 내되 공탁소에 이의신청서를 제출한다(공탁법 제12조) · 공탁관은 이유 있으면 처분을 하고 이유 없으면 5일 이내에 의견을 붙여 법원에 보낸다(제13조)"],["이의 결정","법원은 이유 있으면 상당한 처분을 명하고 결정에는 비송사건절차법에 따라 항고한다(제14조) · 사유신고로 배당절차가 시작되는 등 공탁관이 더 처분할 수 없게 되면 이의는 부적법하다 · 판단은 처분 당시 자료로 한다"]]},{"t":"table","title":"공탁서 정정·대공탁·전자공탁","head":["항목","내용"],"rows":[["공탁서 정정","정정은 수리 뒤 발견한 착오를 공탁의 동일성을 해치지 않는 범위에서만 한다 · 효력은 당초 공탁 때로 소급하되 반대급부 조건 철회는 정정 때부터 효력이 있다 · 근거 법조 정정, 누락한 압류 추가, 주소 착오 정정, 절대적 불확지공탁 뒤 피공탁자 지정은 된다"],["정정 불가","공탁자·피공탁자 변경, 집행공탁을 혼합공탁으로, 불확지공탁을 확지공탁으로 바꾸는 것은 안 된다 · 수령불능 사유 추가, 공탁금액·공탁물 변경도 안 된다 · 공탁금 전부 지급 뒤에는 정정하지 못하고 개명은 정정 사유가 아니다"],["대공탁","대공탁은 공탁 유가증권의 상환금을 금전으로 바꾸어 공탁하는 것이다 · 공탁의 동일성이 유지되어 담보공탁이어도 담보를 명한 관청의 승인이 필요 없다 · 대공탁 후 회수청구권 소멸시효는 대공탁일부터 진행한다"],["부속공탁","대공탁과 부속공탁을 함께 청구하면 별건으로 접수하되 · 기록은 1개로 만들고 공탁서 원본은 첨부하지 않는다"],["전자공탁","전자공탁 신청은 금액 제한이 없지만 5천만원을 넘는 공탁금의 출급·회수는 전자로 못 한다(공탁규칙 제69조) · 법인 아닌 사단·재단과 미성년자는 전자공탁을 못 하고 대리는 변호사·법무사만 한다 · 가상계좌 착오납입은 납입 당일 업무시간 전까지 취소를 요청한다"],["공탁금 이자","공탁금 이자는 연 1만분의 35이고 이율이 바뀌면 기간별로 계산한다 · 압류·추심이나 양도가 있으면 그 뒤에 생긴 이자만 넘어간다 · 전부명령은 송달 뒤 이자만 전부채권자에게 간다"],["담보물변경","담보물변경은 담보제공결정을 한 법원이 결정으로 명한다 · 금전과 유가증권 사이나 유가증권 사이의 변경도 포함한다"]]}],"11":[{"t":"table","title":"변제공탁의 요건과 일부공탁","head":["항목","내용"],"rows":[["변제공탁의 요건","변제공탁은 현존하는 확정채무에 대해 수령거절·수령불능·채권자 불확지 사유가 있을 때 한다(민법 제487조) · 채권자가 미리 수령을 거절했거나 거절할 것이 명백하면 이행제공 없이 공탁할 수 있다 · 가집행선고부 판결 금액, 조세·연금보험료 채무도 공탁 대상이다 · 과거 여러 달 치 차임이나 보상금은 모아서 공탁할 수 있지만 장래분을 미리 공탁하지는 못한다 · 법정대리인 없는 제한능력자 채권자는 수령불능에 해당한다"],["일부공탁","채무 전액을 공탁해야 하고 일부공탁은 채권자가 수락하지 않는 한 그 부분도 효력이 없다 · 근저당 피담보채무가 계속적 거래에서 생긴 여러 채무의 집합이라도 일부공탁은 무효이다 · 채무자 겸 설정자가 최고액만 공탁하면 무효지만 제3취득자는 최고액과 경매비용만 공탁해도 유효하다 · 아주 근소하게 부족하면 신의칙상 유효하고, 보증금에서 연체차임 등을 뺀 나머지 공탁도 유효하다 · 매월 차임 중 1개월분 공탁도 유효하고, 채권자의 수령 의사표시 전이면 추가공탁하면서 채무 내용을 바꿀 수 있다"],["반대급부 조건","채권자가 이행할 의무 없는 조건을 붙인 공탁은 채권자가 수락하지 않으면 공탁 전체가 무효이다 · 어음 반환, 전세권말소는 동시이행이라 조건으로 붙일 수 있지만 채권증서 반환, 임차권등기 말소, 담보 가등기·본등기 말소, 건물 인도 확인서 첨부는 조건이 될 수 없다 · 단순히 협조를 구하는 문구는 조건이 아니다 · 부당한 조건을 철회하는 정정을 하면 그때부터 유효하다 · 피공탁자는 반대급부 이행 증명서면을 내야 출급하고, 공탁자를 상대로 한 별도의 등기 승소판결은 이행 증명서면이 아니다"]]},{"t":"table","title":"불확지공탁·수령·통지","head":["항목","내용"],"rows":[["채권자 불확지공탁","채권양도 통지 철회, 양도금지특약 위반 양도로 양수인의 선의 여부를 알 수 없는 경우, 예금주 다툼, 상속인을 알 수 없는 경우, 장래채권에 대한 여러 전부명령의 합계가 확정 채권액을 넘는 경우에는 불확지공탁을 할 수 있다 · 양도금지특약 있는 채권에 대한 전부명령이 확정된 경우와 확정일자 있는 통지의 도달 선후가 있는 이중양도는 할 수 없다 · 사해행위취소 원상회복청구권 가처분이 송달되면 가처분채무자를 피공탁자로 수령불능 공탁을 한다"],["공탁물 수령과 이의유보","피공탁자가 이의 없이 공탁금을 받으면 공탁원인이 부적법해도 공탁자가 주장한 대로 효과가 생기고, 지정한 채무에 충당된다 · 이의유보 의사표시는 공탁관이나 공탁자에게 하고 묵시적으로도 할 수 있으며 양수인·전부채권자·추심채권자도 할 수 있다 · 공탁원인과 다른 채무로 받는다고 유보하면 어느 채무도 소멸하지 않는다 · 수용보상금도 증액된 금액을 이의유보 없이 받으면 행정소송 중이어도 재결에 승복한 것으로 본다 · 피공탁자가 수락하면 공탁자는 회수하지 못한다(민법 제489조)"],["공탁통지","변제공탁에는 피공탁자 수만큼 공탁통지서를 내고, 공탁관은 공탁물 납입 통지를 받으면 이를 발송한다 · 절대적 불확지나 주소불명 공탁은 신청 때 통지서를 내지 않고 나중에 정정할 때 낸다 · 공탁통지는 유효요건이 아니어서 통지가 없어도 공탁 효력에 영향이 없다 · 공탁통지서는 소송서류가 아니어서 공시송달이나 집행관 특별송달을 쓸 수 없다 · 피공탁자는 발송 전에도 공탁소에 나와 교부를 청구할 수 있다"]]},{"t":"table","title":"수용보상금 공탁과 형사공탁","head":["항목","내용"],"rows":[["수용보상금 공탁","수용 효과를 위해 재결 보상금 전액을 조건 없이 공탁해야 하므로 대납 전기요금, 상속등기 비용을 빼거나 납세증명서 제출, 이전등기 서류 교부, 제한물권 말소를 조건으로 붙이면 무효이다 · 다만 원천징수세액은 빼고 공탁할 수 있다 · 반대조건을 수용개시일 뒤에 철회하면 소급하지 않아 재결이 실효된다 · 피공탁자는 수용개시일 당시 등기부상 소유자이고, 매수인은 출급청구권을 양도받아야 받는다 · 시·군법원 공탁관은 수용보상금 공탁을 받지 않는다"],["수용보상금의 피공탁자","저당권·가압류·경매개시결정이 있어도 피공탁자란에는 토지소유자만 적고, 저당권 소멸 표시도 하지 않는다 · 일반채권자의 압류·가압류는 불확지 사유가 아니다 · 피보전권리가 공시되지 않은 가처분이나 소유권말소청구권 가처분은 ‘소유자 또는 가처분권리자’로 상대적 불확지공탁을 하지만 소유권이전등기청구권 가처분이나 사해행위취소 가처분이면 소유자만 적는다 · 분할 전후 대장상 소유자가 다르면 상대적 불확지, 대장에 성명만 있고 주소가 없으면 절대적 불확지공탁을 한다 · 토지에 대한 체납처분 압류는 보상금에 물상대위되지 않는다"],["형사공탁의 특례","피고인이 피해자 인적사항을 모를 때 형사사건이 계속 중인 법원 소재지 공탁소에 하고(공탁법 제5조의2), 기소 전 피의자는 못 하며 군사법원 사건에도 적용한다 · 공탁서에는 피해자 성명과 법원·사건번호 등을 적고 주소·주민등록번호는 적지 않는다 · 공탁관은 법원과 검찰에 형사공탁사실통지서를 보내고 피공탁자에게는 전자공탁홈페이지 공고로 통지한다 · 동일인 확인 증명서는 법원이나 검찰이 발급해 공탁소로 보내며, 사망한 피해자는 그의 인적사항만 적혀 있으면 된다"]]}],"12":[{"t":"table","title":"권리공탁·의무공탁·추심채권자 공탁","head":["항목","내용"],"rows":[["권리공탁 범위","금전채권 일부가 압류되면 제3채무자는 압류된 금액이나 채권 전액을 공탁할 수 있다(민사집행법 제248조 제1항) · 전부명령이 확정되기 전이어도 된다"],["권리공탁 피공탁자","압류액만 공탁하면 피공탁자란을 비운다 · 전액을 공탁하면 압류채무자를 피공탁자로 적어 초과 부분은 변제공탁이 된다 · 채무자가 출급하거나 공탁자가 회수할 수 있다"],["공탁 후 압류","공탁 뒤 압류가 실효되면 채무자가 집행법원의 지급위탁으로 출급하고 공탁자는 회수하지 못한다 · 공탁 뒤에 송달된 압류는 효력이 없다"],["의무공탁","압류되지 않은 부분을 넘어 거듭 압류·가압류되면 채권자의 청구가 있을 때 · 제3채무자는 채권 전액을 공탁해야 한다(제248조 제3항) · 배당요구가 있으면 압류된 부분을 공탁해야 한다(제2항)"],["의무공탁 효과","이때 한 채권자에게 변제해도 공탁을 청구한 채권자에게는 소멸을 주장하지 못한다 · 공탁을 명하는 추심소송은 추심명령을 받은 채권자만 낼 수 있다"],["추심채권자 공탁","추심채권자가 신고 전에 다른 압류·배당요구가 있으면 추심금을 바로 공탁하고 신고한다 · 체납처분 압류가 있는 채권도 같다(제236조 제2항)"]]},{"t":"table","title":"가압류·체납처분·혼합공탁","head":["항목","내용"],"rows":[["가압류 공탁 근거","피공탁자는 가압류채무자이며 공탁관은 가압류채권자에게 공탁사실을 통지한다(민사집행법 제291조, 제248조 제1항) · 제3채무자는 가압류발령법원에 신고하지만 배당 시작·배당가입 차단 효과는 없다"],["가압류 공탁 후","가압류 효력은 채무자의 출급청구권에 남음, 이의에 따른 취소결정은 확정증명 불필요 · 가압류가 실효되면 채무자가 공탁통지서와 실효 증명으로 공탁관에게 직접 출급한다 · 본압류로 이전되면 공탁관이 사유신고, 채권자는 지급위탁으로 출급한다"],["체납처분 압류 공탁","체납처분 압류만으로는 변제공탁도 집행공탁도 하지 못한다 · 민사집행 압류나 가압류와 체납처분 압류가 함께 있으면 선후와 관계없이 집행공탁을 할 수 있다 · 체납자를 피공탁자로 한 변제공탁은 못 한다"],["체납처분 출급","압류 총액이 채권액을 넘으면 피공탁자란을 비우고 배당절차를 거친다 · 넘지 않으면 체납처분청은 공탁관에게 직접 출급을 청구한다 · 가압류가 임금채권에 기한 것이어도 체납처분 압류채권자는 공탁금을 추심할 수 있다"],["혼합공탁 요건","채권자 불확지 변제공탁 사유와 집행공탁 사유가 함께 있을 때 하고 압류 경합이 꼭 필요하지는 않다 · 피공탁자는 양도인 또는 양수인으로 적고 집행채권자는 적지 않는다"],["혼합공탁 출급","출급하려면 다른 피공탁자와 집행채권자 모두에 대한 권리 증명서면 필요 · 집행채권자는 지급위탁으로 출급한다 · 변제공탁 부분에는 배당가입 차단효가 없다"],["혼합공탁 무효","양도 다툼이 없거나 압류 당시 이미 대항요건을 갖춘 양도가 있는 경우 · 혼합공탁이 무효여서 착오로 회수할 수 있다"]]},{"t":"table","title":"사유신고와 가압류해방공탁·재판상 담보","head":["항목","내용"],"rows":[["공탁관 사유신고","공탁금 지급청구권에 압류가 경합한 경우 공탁관은 다음 날부터 3일 이내 · 먼저 송달된 압류명령의 발령법원에 사유신고를 한다 · 그동안 추심에 응하지 않는다"],["신고 대상 아님","가압류끼리나 가압류와 체납처분만 경합하면 신고 대상이 아니다 · 유가증권·물품공탁이나 양도 후 경합도 대상이 아니다"],["신고 시기","상대적 불확지공탁은 권리 귀속 증명서면이 나온 뒤에 신고한다 · 재판상 담보공탁은 담보취소나 담보권 실행 요건을 갖춘 뒤에 신고한다 · 이미 신고한 뒤의 압류에는 추가 신고를 하지 않는다"],["가압류해방공탁","해방금액은 금전으로만 공탁하고 공동채무자가 자기 몫만 공탁해 일부 취소를 구할 수 없다 · 해방금액 일부만 공탁하면 착오공탁이 된다"],["해방공탁 효력","가압류 효력은 채무자의 공탁금 회수청구권에 미치고 가압류채권자에게 출급청구권이나 우선변제권은 없다 · 가압류채권자는 본안 승소 뒤 회수청구권에 대한 본압류 이전 압류·현금화명령을 받아야 한다 · 다른 채권자가 회수청구권을 압류하면 경합이 되어 공탁관이 사유신고를 한다"],["재판상 담보 범위","강제집행정지 담보는 정지 자체로 생긴 손해를 담보하므로 · 정지 기간의 지연손해금·차임 상당 손해는 포함, 원금이나 근저당권 피담보채권은 아니다 · 권리행사최고에 따라 낸 소송의 비용은 들어간다"],["가압류 담보 등","가압류 담보에는 가압류 취소 소송비용과 정신적 손해가 포함, 본안소송 비용은 제외 · 제3자도 법원 허가나 담보권리자 동의 없이 대신 공탁할 수 있다 · 담보권리자는 질권자와 같은 권리를 가져 회수청구권이 양도되거나 압류되어도 담보권 실행으로 출급한다"]]},{"t":"table","title":"담보취소","head":["항목","내용"],"rows":[["담보 소멸 요건","담보사유는 담보제공자의 승소판결이 확정되어야 소멸한다 · 제1심 담보는 항소심에서 다시 담보를 제공해도 소멸하지 않는다 · 항소심이 제1심을 취소했어도 확정 전이면 소멸하지 않는다"],["담보 소멸 예외","다만 가집행선고부 항소심판결이 상고심에서 파기환송되면 소멸한다 · 보전처분 담보는 본안이 계속 중이면 보전처분이 취소되어도 소멸하지 않는다"],["권리행사 기간","권리행사기간이 지나면 동의가 있는 것으로 본다 · 소를 냈다가 취하하면 권리행사가 없던 것이 된다 · 담보취소결정 확정 전에 권리행사를 증명하면 그 결정을 취소할 수 있다"]]}],"13":[{"t":"table","title":"출급청구권자","head":["항목","내용"],"rows":[["출급청구권자","출급청구권자는 공탁서에 적힌 피공탁자와 그 승계인이고, 실체법상 채권자라도 피공탁자가 아니면 출급하지 못한다 · 제3자가 피공탁자를 상대로 확인판결을 받아도 직접 출급하지 못하고 양도를 받아야 한다 · 피공탁자가 여럿이고 지분이 정해졌으면 자기 지분만 받고, 공유 토지 수용보상금도 각자 지분만큼 청구한다 · 합유자 전원을 피공탁자로 하면 전원이 청구해야 하고, 불가분채권자 2인을 피공탁자로 적었으면 공탁자 동의서가 있어도 혼자 출급하지 못한다"],["수용보상금의 출급","수용개시일 뒤에 이전등기를 마친 매수인, 특조법으로 등기한 자, 명의신탁을 해지한 종중은 수용 당시 소유자로부터 출급청구권을 양도받아야 받는다 · 사업인정고시 뒤 개시일 전에 소유권을 승계한 자는 승계를 증명해 직접 청구할 수 있다 · 공탁서에 甲과 乙이 적혀 있으면 甲이 단독소유를 증명해도 혼자 출급하지 못한다 · 수용보상금 공탁은 피공탁자가 수령을 거절해도 민법 제489조로 회수할 수 없다"],["상대적 불확지공탁의 출급","피공탁자 전원이 함께 청구하면 별도의 증명서면이 필요 없다 · 혼자 청구할 때는 다른 피공탁자의 승낙서나 그를 상대로 한 확인판결을 내고, 공탁자의 승낙서나 공탁자·국가를 상대로 한 판결은 증명서면이 아니다 · 가처분권자가 낀 수용보상금 공탁은 가처분 취하증명이 아니라 가처분권자의 승낙서(인감증명 첨부)가 필요하다 · 절대적 불확지공탁은 공탁자를 상대로 한 확인판결로 출급한다 · 추심채권자도 자기 이름으로 다른 피공탁자를 상대로 확인의 소를 낼 수 있다"],["출급·회수의 첨부서면","개인이 5천만원 이하를 출급하거나 강제집행·체납처분에 따른 청구, 공탁서를 낸 경우에는 공탁통지서를 생략하고, 법인 아닌 사단·법인의 청구에는 생략 특례가 없다 · 회수청구에는 공탁서를 내되 관공서·법인 아닌 사단은 1천만원 이하만 생략하고, 회수청구권 전부채권자는 권리 증명서면을 낸다 · 본인이 1천만원 이하를 직접 청구하고 신분증으로 확인되면 인감증명을 생략하지만 임의대리인이면 낸다 · 법인은 사용인감에 법인 인감증명을 붙이고, 이해관계인 승낙서에는 그의 인감증명을 붙인다"]]},{"t":"table","title":"청구권의 처분과 소멸시효","head":["항목","내용"],"rows":[["출급청구권과 회수청구권","출급청구권과 회수청구권은 별개의 권리여서 한쪽의 양도·압류는 다른 쪽에 영향이 없고, 선후는 공탁관의 인가 때가 아니라 청구한 때로 정한다 · 피공탁자가 공탁소에 서면으로 수락하거나 불수락 표시 없는 양도통지가 도달하면 회수청구권이 소멸한다 · 회수동의서를 냈더라도 실제 회수 전이면 피공탁자는 출급할 수 있다 · 착오공탁이나 원인소멸이면 출급청구권이 없어 그 전부채권자가 받은 돈은 부당이득이다 · 반대급부 조건은 회수에는 제한이 되지 않는다"],["지급청구권의 양도","양도통지는 검찰청을 거치지 않고 공탁관에게 직접 도달해도 유효하고, 양수인이 양도인의 위임을 받아 통지할 수도 있다 · 양도통지서에 인감증명이 없으면 양수인이 청구할 때 양도인의 인감증명을 내고, 양도증서를 공증받았으면 필요 없다 · 양수인은 국가를 상대로 확인판결을 받아도 국가에 양도통지가 되어야 출급한다 · 양도 뒤 양도인이 일방적으로 해제·철회를 통지해도 양수인의 동의가 없으면 효력이 없다"],["소멸시효 기산","공탁금 지급청구권은 행사할 수 있는 때부터 10년이 지나면 시효로 소멸한다(공탁법 제9조 제3항) · 착오공탁의 회수청구권은 공탁일부터, 원인소멸 회수는 소멸한 때부터 진행한다 · 반대급부·조건부 공탁은 이행·성취 때부터, 상대적 불확지공탁은 출급권자가 확정된 때부터, 수령불능·절대적 불확지공탁은 출급청구권을 행사할 수 있게 된 때부터 진행하고, 불확지로 통지하지 못한 동안에는 진행하지 않는다 · 배당에 따른 지급은 증명서 교부일부터, 불출석 배당액 공탁은 공탁일부터 기산한다"],["시효중단과 완성","공탁관의 완결 여부 문의서 발송, 지급할 수 있다는 구두 답변, 안내문 송달, 지급청구권자에 대한 공탁사실증명서 교부, 서면 불비를 이유로 한 불수리결정은 시효를 중단한다 · 일괄 공탁 일부의 지급 인가는 잔액의 시효도 중단한다 · 일반적인 절차 설명, 수락서 제출, 제3자의 압류·가압류는 중단사유가 아니고, 출급청구권과 회수청구권의 중단은 서로 영향이 없다 · 시효가 완성되면 국고 납부 전이라도 지급을 인가하지 않는다"],["형사공탁의 회수 제한","형사사건 피해자를 위한 변제공탁은 민법 제489조나 공탁원인 소멸을 이유로 회수하지 못한다(공탁법 제9조의2) · 다만 피공탁자가 회수에 동의하거나 수령거절 의사를 공탁소에 통고한 경우, 해당 사건에서 무죄판결이 확정되거나 기소유예를 뺀 불기소 결정이 있는 경우에는 회수할 수 있다 · 착오로 공탁한 경우의 회수는 이 제한을 받지 않는다 · 피공탁자의 동의가 있으면 형사사건의 결과와 관계없이 회수할 수 있다"]]}]};
